/* 原版 LifePoint Wwise 音频，依据见 asstesTools/ref/game-export/audio-v3.md。 */
const SOURCES =
{"hover":"data:audio/wav;base64,","select":"data:audio/wav;base64,","paint":"data:audio/wav;base64,","reset":"data:audio/wav;base64,","success":"data:audio/wav;base64,"};
const dbGain = db => Math.pow(10,db/20);

async function create() {
  const context = new AudioContext();
  const master = context.createGain();
  master.connect(context.destination);
  const entries = await Promise.all(Object.entries(SOURCES).map(async ([name,url]) => {
    const raw = atob(url.slice(url.indexOf(",")+1));
    const bytes = Uint8Array.from(raw,char=>char.charCodeAt(0));
    return [name,await context.decodeAudioData(bytes.buffer)];
  }));
  const buffers = Object.fromEntries(entries);
  let paused = false;
  let unlocked = false;
  const paintVoices = new Set();
  function play(name,gain=1,cents=0,delay=0) {
    if (!unlocked || paused) return;
    const source = context.createBufferSource();
    const level = context.createGain();
    source.buffer = buffers[name];
    source.detune.value = cents;
    level.gain.value = gain;
    source.connect(level).connect(master);
    const voice = {source,level};
    if (name==="paint") paintVoices.add(voice);
    source.onended = () => { paintVoices.delete(voice); source.disconnect(); level.disconnect(); };
    source.start(context.currentTime+delay);
  }
  return Object.freeze({
    unlock() { unlocked=true; return paused ? Promise.resolve() : context.resume(); },
    hover() { play("hover"); },
    selectColor() { play("select"); },
    paintWave(order) {
      if (!unlocked || paused) return;
      // 原版事件的声音／ActorMixer 链只使用 spreads_counting 参数。
      const t = Math.min(20,Math.max(0,order))/20;
      const cents = -720+(1592+720)*t;
      // Wwise 的 Scaling=dB 保存振幅偏移曲线；音量另外叠加 -2 dB。
      const gain = (1-0.35398218+(-0.12345645+0.35398218)*t)*dbGain(-2);
      // 原版 SetRTPCValue 全局生效，也会调整正在播放的染色尾音。
      for (const voice of paintVoices) {
        voice.source.detune.setValueAtTime(cents,context.currentTime);
        voice.level.gain.setValueAtTime(gain,context.currentTime);
      }
      play("paint",gain,cents);
    },
    // Complete 序列在第 400 个时间刻度触发此事件，TickResolution=24000。
    success() { play("success",dbGain(-7),0,400/24000); },
    // Renew 序列在第 0 个时间刻度播放原版 life_point_open 事件。
    reset() { play("reset",dbGain(-2)); },
    pause() { paused=true; return context.suspend(); },
    resume() { paused=false; return unlocked ? context.resume() : Promise.resolve(); },
    setMuted(muted) { master.gain.setValueAtTime(muted?0:1,context.currentTime); }
  });
}
export const GameAudio=Object.freeze({create});
